<script setup lang="ts">
import {ref,onMounted} from 'vue';
type Row=Record<string,any>;
const token=ref(sessionStorage.getItem('hr-token')??''), account=ref(''), password=ref(''), error=ref(''), message=ref(''), busy=ref(false);
const capability=ref<Row|null>(null), people=ref<Row[]>([]), contracts=ref<Row[]>([]), total=ref(0), cursor=ref(0);
const uploadKey=ref(0);
const reminders=ref<Row[]>([]), selected=ref<Row|null>(null), history=ref<Row[]>([]);
const form=ref<Row>({employeeId:'',title:'',startsOn:'',endsOn:'',attachmentId:'',recipients:[],version:0}), editing=ref('');
function clearPrivate(){capability.value=null;people.value=[];contracts.value=[];reminders.value=[];selected.value=null;history.value=[];reset();}
async function response(r:Response){if(r.status===401||r.status===403)clearPrivate();const data=await r.json().catch(()=>({message:'企业服务返回异常，请稍后重试'}));if(!r.ok)throw new Error(data.message??'请求失败');return data;}
async function api(path:string,method='GET',body?:unknown){return response(await fetch('/api'+path,{method,headers:{Authorization:'Bearer '+token.value,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined}));}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function load(){capability.value=await api('/hr/me');people.value=[];for(let offset=0;;offset+=100){const batch=await api('/hr/employees?cursor='+offset+'&limit=100');people.value.push(...batch);if(batch.length<100)break;}reminders.value=await api('/hr/reminders');const list=await api('/hr/contracts?cursor='+cursor.value+'&limit=20');contracts.value=list.items;total.value=list.total;}
async function login(){await act(async()=>{const data=await api('/auth/login','POST',{account:account.value,password:password.value});password.value='';token.value=data.token;sessionStorage.setItem('hr-token',token.value);await load();});}
function logout(){token.value='';sessionStorage.removeItem('hr-token');capability.value=null;people.value=[];contracts.value=[];reminders.value=[];selected.value=null;history.value=[];reset();}
function reset(){uploadKey.value++;editing.value='';form.value={employeeId:'',title:'',startsOn:'',endsOn:'',attachmentId:'',recipients:[],version:0};}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await act(async()=>{const b=new FormData();b.append('file',file);const r=await fetch('/api/attachments',{method:'POST',headers:{Authorization:'Bearer '+token.value},body:b});const data=await response(r);form.value.attachmentId=data.id;message.value='附件已上传，请保存合同完成归档';});}
async function save(){await act(async()=>{await api('/hr/contracts'+(editing.value?'/'+editing.value:''),editing.value?'PUT':'POST',form.value);reset();await load();message.value='合同已归档';});}
async function view(id:string){await act(async()=>{selected.value=await api('/hr/contracts/'+id);history.value=await api('/hr/contracts/'+id+'/history');});}
async function edit(row:Row){await act(async()=>{const d=await api('/hr/contracts/'+row.id);editing.value=d.id;form.value={employeeId:d.employee_id,title:d.title,startsOn:String(d.starts_on).slice(0,10),endsOn:String(d.ends_on).slice(0,10),attachmentId:d.attachment_id,recipients:d.recipients,version:d.version};});}
async function download(row:Row){await act(async()=>{const r=await fetch('/api/attachments/'+row.attachment_id,{headers:{Authorization:'Bearer '+token.value}});if(!r.ok){if(r.status===401||r.status===403)clearPrivate();throw new Error('无权下载或附件不可用');}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='合同附件';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
async function grant(person:Row,event:Event){const level=(event.target as HTMLSelectElement).value;await act(async()=>{await api('/hr/grants/'+person.id,'PUT',{access:level,version:person.grant_version});await load();message.value='授权已更新';});}
async function duties(person:Row){await act(async()=>{await api('/hr/employees/'+person.id+'/duties','PUT',{duties:person.duties,version:person.duties_version});await load();message.value='职责已保存';});}
async function page(delta:number){await act(async()=>{cursor.value=Math.max(0,cursor.value+delta);await load();});}
onMounted(()=>{if(token.value)void act(load);});
</script>
<template><main class="hr-shell"><h1>员工档案与合同</h1><p>合同资料仅限授权人员查看。到期前30天、7天及当天向指定人员发送站内提醒。</p>
<p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
<form v-if="!capability" @submit.prevent="login"><label>账号<input v-model="account" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><button :disabled="busy">登录人事入口</button></form>
<template v-else><button @click="logout">退出</button><button :disabled="busy" @click="act(load)">刷新</button><a v-if="capability.admin" href="/">管理员后台</a>
<section><h2>我的合同提醒</h2><p v-if="!reminders.length">暂无到期提醒</p><p v-for="n in reminders" :key="n.id"><button :disabled="busy" @click="view(n.object_id)">{{n.title}} · 到期日 {{String(n.ends_on).slice(0,10)}}</button></p></section><section><h2>员工档案</h2><p v-if="!people.length">暂无员工</p><article v-for="p in people" :key="p.id"><h3>{{p.name}}</h3><p>部门：{{p.department_name || '未分配'}} · 岗位：{{({NONE:'未设置',GENERAL_MANAGER:'总经理',DEPUTY_GENERAL_MANAGER:'副总经理'} as Record<string,string>)[p.business_position] ?? p.business_position}}</p><label>工作职责<textarea v-model="p.duties" :readonly="!capability.manage" maxlength="4000"/></label><button v-if="capability.manage" :disabled="busy" @click="duties(p)">保存职责</button><label v-if="capability.admin">合同权限<select :value="p.access" :disabled="busy" @change="grant(p,$event)"><option value="NONE">无授权</option><option value="READ">只读</option><option value="MANAGE">管理</option></select></label></article></section>
<section v-if="capability.manage"><h2>{{editing?'修订合同':'归档合同'}}</h2><form @submit.prevent="save"><label>员工<select v-model="form.employeeId" aria-label="员工" required><option value="">请选择</option><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>合同名称<input v-model="form.title" maxlength="200" required></label><label>开始日期<input v-model="form.startsOn" type="date" required></label><label>到期日期<input v-model="form.endsOn" type="date" :min="form.startsOn" required></label><label v-if="!editing">合同专用附件<input :key="uploadKey" type="file" @change="upload"></label><p v-if="form.attachmentId">附件已就绪</p><label>提醒接收人（可多选）<select v-model="form.recipients" multiple required><option v-for="p in people.filter(p=>p.status==='ACTIVE' && (p.access!=='NONE' || p.is_admin))" :key="p.id" :value="p.id">{{p.name}}</option></select></label><p>接收人必须拥有合同访问权限，服务器会再次检查。</p><button :disabled="busy||!form.attachmentId">保存合同</button><button type="button" @click="reset">取消</button></form></section>
<section v-if="selected"><h2>合同详情：{{selected.title}}</h2><p>{{selected.starts_on}} 至 {{selected.ends_on}}</p><button :disabled="busy" @click="download(selected)">下载此合同</button><h3>修订记录</h3><p v-for="v in history" :key="v.version">版本 {{v.version}} · {{v.snapshot.title}} · {{v.snapshot.starts_on}} 至 {{v.snapshot.ends_on}}</p><button @click="selected=null">关闭详情</button></section>
<section><h2>已归档合同（{{total}}）</h2><p v-if="!contracts.length">暂无合同</p><article v-for="c in contracts" :key="c.id"><h3>{{c.title}}</h3><p>{{c.employee_name}} · {{String(c.starts_on).slice(0,10)}} 至 {{String(c.ends_on).slice(0,10)}}</p><button :disabled="busy" @click="view(c.id)">查看详情</button><button :disabled="busy" @click="download(c)">下载合同</button><button v-if="capability.manage" :disabled="busy" @click="edit(c)">修订</button></article><button :disabled="busy||cursor===0" @click="page(-20)">上一页</button><button :disabled="busy||cursor+20>=total" @click="page(20)">下一页</button></section>
</template></main></template>
<style scoped>.hr-shell{max-width:1000px;margin:auto;padding:24px;color:#243b35}.hr-shell{overflow-wrap:anywhere}.hr-shell section{margin-top:24px}.hr-shell article{padding:16px;border:1px solid #cbd6cd;border-radius:12px;margin:12px 0}.hr-shell label{display:flex;flex-direction:column;gap:6px;margin:12px 0}.hr-shell input,.hr-shell select,.hr-shell textarea{box-sizing:border-box;max-width:100%;padding:10px}.hr-shell button{margin:5px;padding:10px;cursor:pointer}.hr-shell [role=alert]{color:#a12020}.hr-shell textarea{min-height:70px}</style>
